pre.code:
foo :: proc() -> (int, bool, string) { ... }
bar :: proc(int, bool, string) { ... }

bar(foo())

x, y, z, w := 1.34, foo() // N-variables on the LHS, N-values on the RHS

blaz :: proc() -> (bool, string) { ... }
bar(1, blaz())

m: map[string]int
x: union{int, bool}

value, ok := m[key] // map access

v, ok := x.(int) // type assertion

// a type switch statement is more commonly seen as more cases may need to be handled
switch y in x {
case int:  ...
case bool: ...
case:      ... 
}

x, err := foo();
if err != nil {
    return err;
}

a: string  = "Hellope!";
b: cstring = "Hellope!";
c: bool    = true;
d: b32     = true;
e: rune    = '\n';
f: i32     = '\n'; // rune literals can be treated as just numbers

MY_AWESOME_SOCK_COUNT :: 123.0; // named constant without a concrete type

a: i32 = MY_AWESOME_SOCK_COUNT;
b: f32 = MY_AWESOME_SOCK_COUNT;

foo :: proc(x: int) -> (val: int, err: Error) {
	defer if err != nil {
		// handle clean up
	}

	if x > 0 {
		err = .Bad_Error;
	} else {
		val = -x*2 + 1;
	}

	// returns all the named return values without having the manual specify them
	return;
}

the_cases: switch x {
case 1:
	loop: for y > 0 {
		do_thing(&y);
		if y == 3 {
			break the_cases;
		} else if y == 2 {
			continue loop;
		}
		do_other_thing(&y);
	}
case 2, 3:
	do_thing(&y);
	fallthrough;
case 4:
	do_other_thing(&y);
}

pub struct Foo {
	value: i32,
}

fn main() {
	let foo = Foo{value: 123};
	let bar = foo; // the responsibility of `foo` is transferred to `bar`

	println!("{}", foo.value); // error: use of moved value: `foo.value`
	println!("{}", bar.value);
}
